@Test
    public void testReflectionHierarchyHashCode() {
        assertEquals(17 * 37 * 37, HashCodeBuilder.reflectionHashCode(new TestSubObject(0, 0, 0)));
        assertEquals(17 * 37 * 37 * 37, HashCodeBuilder.reflectionHashCode(new TestSubObject(0, 0, 0), true));

        final int withoutTransients = HashCodeBuilder.reflectionHashCode(new TestSubObject(123456, 7890, 0));
        assertTrue(withoutTransients == (17 * 37 + 7890) * 37 + 123456
                || withoutTransients == (17 * 37 + 123456) * 37 + 7890);

        final int withTransients = HashCodeBuilder.reflectionHashCode(new TestSubObject(123456, 7890, 0), true);
        final int[] values = {123456, 7890, 0};
        boolean matchesPermutation = false;
        for (int i = 0; i < values.length && !matchesPermutation; i++) {
            for (int j = 0; j < values.length && !matchesPermutation; j++) {
                if (j == i) {
                    continue;
                }
                for (int k = 0; k < values.length; k++) {
                    if (k == i || k == j) {
                        continue;
                    }
                    int expected = 17;
                    expected = expected * 37 + values[i];
                    expected = expected * 37 + values[j];
                    expected = expected * 37 + values[k];
                    if (withTransients == expected) {
                        matchesPermutation = true;
                        break;
                    }
                }
            }
        }
        assertTrue(matchesPermutation);
    }

