        byte[] bytesFromOldImplementation = ByteUtils.toBytes(JacksonUtils.toJson(restResult));
        String oldJson = new String(bytesFromOldImplementation, Charset.forName(Constants.ENCODE));
        JsonNode oldJsonNode = JacksonUtils.toObj(oldJson, JsonNode.class);
        Assert.assertEquals(jsonNode, oldJsonNode);
    }

