@Test
	public void checkMerge_1() throws Exception {
		Map<String, ?> merged = Maps.merge(
			Stream.of(getClass().getField("one").getAnnotations()).collect(Collectors.toList()));

		Map<String, Object> normalized = new HashMap<>();
		for (Map.Entry<String, ?> entry : merged.entrySet()) {
			Object value = entry.getValue();
			if (value instanceof Iterable) {
				List<Object> sorted = new ArrayList<>();
				for (Object element : (Iterable<?>) value) {
					sorted.add(element);
				}
				sorted.sort((left, right) -> left.toString().compareTo(right.toString()));
				normalized.put(entry.getKey(), sorted);
			}
			else {
				normalized.put(entry.getKey(), value);
			}
		}

		Assert.assertEquals(
			Maps.of(
				"a", Arrays.asList("bar", "baz", "foo"),
				"cpt3", true,
				"b", Arrays.asList(1, 1, 1, 2, 2),
				"c", true),
			normalized);
	}

